from pathlib import Path
import json,html
P=Path(__file__).resolve().parent; R=P.parents[2]
C=P/'compositions';C.mkdir(exist_ok=True)
# Projected geometry from the repository, not invented boundaries.
blocks=json.loads((R/'data/generated/blocks.json').read_text())
coords=[v for b in blocks for ring in b['geometry']['coordinates'] for v in ring]
lo=[min(v[0] for v in coords),min(v[1] for v in coords)];hi=[max(v[0] for v in coords),max(v[1] for v in coords)]
scale=min(680/((hi[0]-lo[0])*.9),780/(hi[1]-lo[1]))
paths=[]
for i,b in enumerate(blocks):
 ring=b['geometry']['coordinates'][0]
 pts=[(60+(v[0]-lo[0])*.9*scale,820-(v[1]-lo[1])*scale) for v in ring]
 d='M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+' Z'
 paths.append(f'<path class="block" d="{d}" fill="'+('#d87a63' if i>=10 else ['#345e41','#507849','#76995b','#a0bc6c'][i%4])+'"/>')
mapSvg='<svg class="geomap" viewBox="0 0 800 880" xmlns="http://www.w3.org/2000/svg">'+''.join(paths)+'</svg>'
