  pos=t-.17+k*.022
  js+=f"tl.fromTo('#shutter-{k}',{{x:-1920}},{{x:0,duration:.17,ease:'power3.in',immediateRender:false}},{pos});tl.to('#shutter-{k}',{{x:1920,duration:.18,ease:'power3.out'}},{t+k*.022});"
