master=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>AgriClimate / Silent 28</title><script src="assets/gsap.min.js"></script><style>html,body{{width:100%;height:100%;margin:0;overflow:hidden;background:#10231a}}#silent-short{{position:relative;width:100%;height:100%;overflow:hidden}}.clip{{position:absolute;inset:0}}.shutter{{position:absolute;left:0;width:100%;height:271px;z-index:30;pointer-events:none}}#progress{{position:absolute;left:0;bottom:0;height:5px;width:100%;background:#d8f78b;transform-origin:left;z-index:25}}</style></head><body><div id="silent-short" data-composition-id="silent-short" data-duration="28" data-width="1920" data-height="1080" data-fps="30">{''.join(hosts)}<div id="progress" data-layout-ignore></div>{shutters}</div><script>const tl=gsap.timeline({{paused:true}});tl.fromTo('#progress',{{scaleX:0}},{{scaleX:1,duration:28,ease:'none'}},0);tl.set('.shutter',{{x:-1920}},0);{js}window.__timelines['silent-short']=tl;</script></body></html>'''
